import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';

import { OffCodeComponent } from './off-code.component';

const routes: Routes = [{ path: '', component: OffCodeComponent }];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class OffCodeRoutingModule { }
