/* eslint-disable max-len */
/* eslint-disable no-var */
import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ToastController, LoadingController, AlertController } from '@ionic/angular';
import { UserService } from '../../../../../data/service/user/user.service';
import { SharedIonic } from '../../../../../core/common/SharedIonic';
import { GResponse } from '../../../../../core/common/GResponse';
import { AddOrUpdateOffCodeModel, IAddOrUpdateOffCodeModel } from '../../../../../data/model/person/BuyerUserModel';

@Component({
  selector: 'app-off-code',
  templateUrl: './off-code.component.html',
  styleUrls: ['./off-code.component.scss']
})
export class OffCodeComponent implements OnInit {

  selectedCategory = 'add';
  searchTitle = '';
  addForm: FormGroup;
  updateForm: FormGroup;
  selectedOffCodeId = 0;
  offCodes: IAddOrUpdateOffCodeModel[];
  selected = false;
  dateNow = new Date().getFullYear().toString() + '-' + (+(new Date().getMonth() + 1) < 10 ? ('0' + +(new Date().getMonth() + 1).toString()) : +(new Date().getMonth() + 1).toString()) + '-' + (+(new Date().getDate()) < 10 ? ('0' + new Date().getDate().toString()) : new Date().getDate().toString()) + 'T' + (+(new Date().getHours()) < 10 ? ('0' + new Date().getHours().toString()) : new Date().getHours().toString()) + ':' + (+(new Date().getMinutes()) < 10 ? ('0' + new Date().getMinutes().toString()) : new Date().getMinutes().toString());

  constructor(
    private userService: UserService,
    private fb: FormBuilder,
    public toastController: ToastController,
    public loadingController: LoadingController,
    public alertController: AlertController
  ) { }

  ngOnInit(): void {

    this.addForm = this.fb.group({
      offCode: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(200)]],
      offPercent: [0, [Validators.min(0), Validators.max(100)]],
      offPrice: [0, [Validators.min(0), Validators.max(100000000)]],
      isShow: [false, [Validators.required]],
      isCourse: [false, [Validators.required]],
      isProduct: [false, [Validators.required]],
      isPriceOff: [false, [Validators.required]],
      oneUserOnly: [false, [Validators.required]],
      buyerUserId: [0, []],
      oneCourseOnly: [false, [Validators.required]],
      courseId: [0, []],
      isLimited: [false, [Validators.required]],
      limitDate: [this.dateNow, []]
    });

    this.updateForm = this.fb.group({
      offCode: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(200)]],
      offPercent: [0, [Validators.min(0), Validators.max(100)]],
      offPrice: [0, [Validators.min(0), Validators.max(100000000)]],
      isActive: [false, [Validators.required]],
      isShow: [false, [Validators.required]],
      isCourse: [false, [Validators.required]],
      isProduct: [false, [Validators.required]],
      isPriceOff: [false, [Validators.required]],
      oneUserOnly: [false, [Validators.required]],
      buyerUserId: [0, []],
      oneCourseOnly: [false, [Validators.required]],
      courseId: [0, []],
      isLimited: [false, [Validators.required]],
      limitDate: [this.dateNow, []]
    });
  }

  public setQueryParams() {

    SharedIonic.loading(this.loadingController);

    if (this.searchTitle == '') {

      this.userService.GetAdminAllOffCodes().subscribe(
        res2 => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res2.status) {
            this.offCodes = res2.data;
            this.selected = false;
            this.selectedOffCodeId = 0;
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    } else {
      this.userService.GetAdminAllOffCodesById(+this.searchTitle).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {
            this.offCodes = [];
            this.offCodes.push(res.data);
          } else if (GResponse.NotFoundStatus === res.status) {
            this.offCodes = [];
            SharedIonic.unSuccessToast(this.toastController);
          } else {
            SharedIonic.unSuccessToast(this.toastController);
            this.offCodes = [];
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

  async presentAlertConfirm(index) {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به حذف هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'حذف',
          handler: () => {
            this.onDelete(index);
          }
        }
      ]
    });

    await alert.present();
  }

  onDelete(index: number | string): void {

    this.selectedOffCodeId = this.offCodes[index].id;

    SharedIonic.loading(this.loadingController);

    this.userService.AdminDeleteOffCode(this.selectedOffCodeId).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {

          this.offCodes[index].isDelete = true;
          this.selectedOffCodeId = 0;
          this.selected = false;
          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
          this.selectedOffCodeId = 0;
          this.selected = false;
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
        this.selectedOffCodeId = 0;
        this.selected = false;
      }
    );
  }

  async presentAlertConfirm0(index) {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به برگرداندن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'برگرداندن',
          handler: () => {
            this.onRestore(index);
          }
        }
      ]
    });

    await alert.present();
  }

  onRestore(index: number | string): void {

    this.selectedOffCodeId = this.offCodes[index].id;

    SharedIonic.loading(this.loadingController);

    this.userService.AdminRestoreOffCode(this.selectedOffCodeId).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {

          this.offCodes[index].isDelete = false;
          this.selectedOffCodeId = 0;
          this.selected = false;
          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
          this.selectedOffCodeId = 0;
          this.selected = false;
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
        this.selectedOffCodeId = 0;
        this.selected = false;
      }
    );
  }

  ionViewWillEnter() {

    SharedIonic.loading(this.loadingController);

    this.userService.GetAdminAllOffCodes().subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {
          this.offCodes = res.data;
        } else if (GResponse.NotFoundStatus === res.status) {
          // SharedIonic.unSuccessToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  async presentAlertConfirm3() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به آپدیت هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onAdd();
          }
        }
      ]
    });

    await alert.present();
  }

  async presentAlertConfirm2() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به آپدیت هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onUpdate();
          }
        }
      ]
    });

    await alert.present();
  }

  onSelect(id: number | string, index: number | string): void {

    this.selectedOffCodeId = +id;
    let y = this.dateNow;

    if (this.offCodes[+index].limitDate != null) {
      const x = this.offCodes[+index].limitDate.toString().lastIndexOf(':');
      y = this.offCodes[+index].limitDate.toString().slice(0, x);
    }

    this.updateForm.setValue({
      offCode: this.offCodes[+index].offCode,
      offPercent: this.offCodes[+index].offPercent,
      offPrice: this.offCodes[+index].offPrice,
      isActive: this.offCodes[+index].isActive,
      isShow: this.offCodes[+index].isShow,
      isCourse: this.offCodes[+index].isCourse,
      isProduct: this.offCodes[+index].isProduct,
      isPriceOff: this.offCodes[+index].isPriceOff,
      isLimited: this.offCodes[+index].isLimited,
      limitDate: y,
      oneUserOnly: this.offCodes[+index].oneUserOnly,
      buyerUserId: this.offCodes[+index].buyerUserId,
      oneCourseOnly: this.offCodes[+index].oneCourseOnly,
      courseId: this.offCodes[+index].courseId
    });

    this.selected = true;
  }

  onCancel(): void {

    this.selectedOffCodeId = 0;
    this.selected = false;
  }

  onUpdate(): void {

    if (this.updateForm.valid) {

      SharedIonic.loading(this.loadingController);

      this.userService.AddOffCodeByAdminId(
        new AddOrUpdateOffCodeModel(
          this.selectedOffCodeId,
          this.updateForm.value.offCode,
          this.updateForm.value.offPercent,
          this.updateForm.value.isActive,
          this.updateForm.value.isShow,
          this.updateForm.value.isCourse,
          this.updateForm.value.isProduct,
          this.updateForm.value.isPriceOff,
          this.updateForm.value.offPrice,
          this.updateForm.value.isLimited,
          this.updateForm.value.limitDate,
          this.updateForm.value.oneUserOnly,
          this.updateForm.value.buyerUserId,
          this.updateForm.value.oneCourseOnly,
          this.updateForm.value.courseId
        )
      ).subscribe(
        res => {

          if (GResponse.SuccessStatus === res.status) {

            this.userService.GetAdminAllOffCodes().subscribe(
              res2 => {
                SharedIonic.dismissLoading(this.loadingController);
                if (GResponse.SuccessStatus === res2.status) {
                  SharedIonic.successToast(this.toastController);
                  this.offCodes = res2.data;
                  this.selected = false;
                  this.selectedOffCodeId = 0;
                } else {
                  SharedIonic.unSuccessToast(this.toastController);
                }
              },
              err => {
                SharedIonic.dismissLoading(this.loadingController);
                SharedIonic.unSuccessToast(this.toastController);
              }
            );

          } else {
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

  onAdd(): void {

    this.selectedOffCodeId = 0;
    this.selected = false;

    if (this.addForm.valid) {

      SharedIonic.loading(this.loadingController);

      this.userService.AddOffCodeByAdminId(
        new AddOrUpdateOffCodeModel(
          null,
          this.addForm.value.offCode,
          this.addForm.value.offPercent,
          true,
          this.addForm.value.isShow,
          this.addForm.value.isCourse,
          this.addForm.value.isProduct,
          this.addForm.value.isPriceOff,
          this.addForm.value.offPrice,
          this.addForm.value.isLimited,
          this.addForm.value.limitDate,
          this.addForm.value.oneUserOnly,
          this.addForm.value.buyerUserId,
          this.addForm.value.oneCourseOnly,
          this.addForm.value.courseId
        )
      ).subscribe(
        res => {

          if (GResponse.SuccessStatus === res.status) {

            this.userService.GetAdminAllOffCodes().subscribe(
              res2 => {
                SharedIonic.dismissLoading(this.loadingController);
                if (GResponse.SuccessStatus === res2.status) {
                  SharedIonic.successToast(this.toastController);
                  this.offCodes = res2.data;
                  this.addForm.setValue({
                    offCode: '',
                    offPercent: '',
                    offPrice: '',
                    isShow: false,
                    isCourse: false,
                    isProduct: false,
                    isPriceOff: false,
                    isLimited: false,
                    limitDate: this.dateNow,
                    oneUserOnly: false,
                    buyerUserId: 0,
                    oneCourseOnly: false,
                    courseId: 0
                  });
                } else {
                  SharedIonic.unSuccessToast(this.toastController);
                }
              },
              err => {
                SharedIonic.dismissLoading(this.loadingController);
                SharedIonic.unSuccessToast(this.toastController);
              }
            );
          } else {
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }
}
